import{_ as t,c as n,a2 as e,o as r}from"./chunks/framework.BnrAgU0Y.js";const l="/bllm/assets/2c29630c1f37283900ae993c15c8df2f.BMjUSS72.png",d=JSON.parse('{"title":"顺序任务代理","description":"顺序任务代理","frontmatter":{"title":"顺序任务代理","description":"顺序任务代理","layout":"doc"},"headers":[],"relativePath":"langflow/tutorials-sequential-agent.md","filePath":"langflow/tutorials-sequential-agent.md"}'),s={name:"langflow/tutorials-sequential-agent.md"};function o(i,a,g,p,c,h){return r(),n("div",null,a[0]||(a[0]=[e('<h1 id="顺序任务代理" tabindex="-1">顺序任务代理 <a class="header-anchor" href="#顺序任务代理" aria-label="Permalink to &quot;顺序任务代理&quot;">​</a></h1><p>为多代理应用程序构建一个 <strong>顺序任务代理</strong> 流，使用多个 <strong>Agent</strong>（代理）组件。</p><p>每个代理都有一个 LLM 模型和一套独特的工具可供使用，<strong>Prompt</strong>（提示）组件连接到 <strong>Agent Instructions</strong>（代理指令）字段以控制代理的行为。例如，<strong>Researcher Agent</strong>（研究员代理）有一个 <strong>Tavily AI 搜索</strong> 组件作为工具连接。<strong>Prompt</strong>（提示）指导代理如何回答您的查询，格式化响应，并将查询和研究结果传递给流中的下一个代理。</p><p>流中的每个后续代理都基于前一个代理的工作，创建解决复杂问题的推理链。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li><a href="https://platform.openai.com/" target="_blank" rel="noreferrer">一个 OpenAI API 密钥</a></li><li><a href="https://www.tavily.com/" target="_blank" rel="noreferrer">一个 Tavily AI API 密钥</a></li></ul><h2 id="打开-langflow-并创建一个新流程" tabindex="-1">打开 Langflow 并创建一个新流程 <a class="header-anchor" href="#打开-langflow-并创建一个新流程" aria-label="Permalink to &quot;打开 Langflow 并创建一个新流程&quot;">​</a></h2><ol><li>点击 <strong>New Flow</strong>，然后选择 <strong>Sequential Tasks Agent</strong>。这将打开一个包含运行流程所需组件的起始模板。</li></ol><p><img src="'+l+`" alt="Starter flow for Sequential Tasks Agent"></p><p>顺序任务代理流程由以下组件组成：</p><ul><li><strong>代理（Agent）</strong> 组件使用连接的LLM（大型语言模型）来分析用户的输入，并在连接的工具中进行选择以完成任务。</li><li><strong>聊天输入（Chat Input）</strong> 组件接受用户在聊天中的输入。</li><li><strong>提示（Prompt）</strong> 组件将用户输入与用户定义的提示结合。</li><li><strong>聊天输出（Chat Output）</strong> 组件将流程的输出打印到聊天窗口。</li><li><strong>YFinance</strong> 工具组件提供从Yahoo Finance获取财务数据的途径。</li><li><strong>Tavily AI搜索（Tavily AI Search）</strong> 工具组件执行由AI驱动的网页搜索。</li><li><strong>计算器（Calculator）</strong> 工具组件执行数学计算。</li></ul><h2 id="运行顺序任务代理流程" tabindex="-1">运行顺序任务代理流程 <a class="header-anchor" href="#运行顺序任务代理流程" aria-label="Permalink to &quot;运行顺序任务代理流程&quot;">​</a></h2><ol><li>将你的 OpenAI API 密钥添加到**Agent（代理）**组件中。</li><li>将你的 Tavily API 密钥添加到<strong>Tavily</strong>组件中。</li><li>点击**Playground（操场）**以通过模板的默认问题开始一次聊天会话。</li></ol><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_10               Should I invest in Tesla (TSLA) stock right now?</span></span>
<span class="line"><span>_10               Please analyze the company&#39;s current position, market trends,</span></span>
<span class="line"><span>_10               financial health, and provide a clear investment recommendation.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这个问题为代理提供了关于如何进行以及回答什么问题的明确指示。</p><ol start="4"><li>在<strong>Playground（操场）<strong>中，检查答案以了解代理如何利用</strong>Tavily AI 搜索</strong>工具进行查询研究，使用<strong>YFinance</strong>工具分析股票数据，以及使用<strong>计算器</strong>判断该股票是否为明智的投资。</li><li>提出类似问题，以观察代理如何利用这些工具回答你的查询。</li></ol><h2 id="后续步骤" tabindex="-1">后续步骤 <a class="header-anchor" href="#后续步骤" aria-label="Permalink to &quot;后续步骤&quot;">​</a></h2><p>要创建您自己的多代理流程，请参阅 <a href="https://your-site.com/agents-tool-calling-agent-component" target="_blank" rel="noreferrer">创建一个解决问题的代理</a>。</p>`,18)]))}const m=t(s,[["render",o]]);export{d as __pageData,m as default};
